// WHOLESALE CAROUSEL
.wholesale-carousel {
    width: 100%;
    margin: 0;
    padding: 0;
    line-height: 0;
    font-size: 0;
    position: relative;
}
.custom-carousel {
    width: 100%;
    margin: 0;
    padding: 0;
    line-height: 0;
}
.custom-carousel .carousel-slide {
    position: relative;
    margin: 0;
    padding: 0;
    line-height: 0;
}
.custom-carousel img {
    width: 100%;
    display: block;
    margin: 0;
    padding: 0;
}
.slick-slider {
    margin-bottom: 0 !important;
}
.slick-list {
    margin: 0 !important;
    padding: 0 !important;
}
.custom-carousel .slick-arrow {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    z-index: 1;
    width: 40px;
    height: 40px;
    background: rgba(0,0,0,0.5);
    border-radius: 50%;
    cursor: pointer;
}
.custom-carousel .slick-prev {
    left: 20px;
}
.custom-carousel .slick-next {
    right: 20px;
}
.custom-carousel .slick-dots {
    position: absolute;
    bottom: 20px;
    left: 0;
    right: 0;
    text-align: center;
    margin: 0;
    padding: 0;
    list-style: none;
    z-index: 1;
}
.custom-carousel .slick-dots li {
    display: inline-block;
    margin: 0 5px;
}
.custom-carousel .slick-dots button {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: white;
    border: none;
    font-size: 0;
    padding: 0;
    cursor: pointer;
}
.custom-carousel .slick-dots .slick-active button {
    background: #000;
}

// CUSTOM BRAND BUTTONS
.brand-button {
        width: 210px;
        height: 50px;
        position: relative;
        font-weight: bold;
        font-size: 20px;
        font-family: "Rajdhani", Arial, Helvetica, sans-serif;
        background-color: #fdcb6e;
        cursor: pointer;
        box-shadow: 5px 5px 0 0 rgba(0,0,0,0.3);
        transition: 0.3s;
        display: flex;
        justify-content: center;
        align-items: center;
        text-decoration: none;
        margin: 10px auto;
        border-radius: 10px;
        @media (max-width: 768px) {
            width: 150px;
            height: 40px; 
            font-size: 12px; 
            margin: 5px; 
            box-shadow: 3px 3px 0 0 rgba(0,0,0,0.3);
            
            &:hover {
                box-shadow: -3px -3px 0 0 rgba(0,0,0,0.3);
            }
        }
        
    }

    .brand-button span {
        color: #fff;
        z-index: 2;
        position: relative;
        font-weight: 600;
        letter-spacing: 1px;
    }

    .brand-button::after {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        opacity: 0;
        transition: 0.3s;
        border-radius: 10px;
    }

    .brand-button:hover {
        box-shadow: -5px -5px 0 0 rgba(0,0,0,0.3);
        transform: scale(0.95);
    }

    .brand-button:hover::after {
        opacity: 1;
    }

    /* Brand-specific gradient backgrounds */
    .porsche::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .ferrari::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .lamborghini::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .mclaren::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .bmw::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .corvette::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .aston::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .bentley::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .audi::after { background: linear-gradient(45deg, #e96443, #904e95); }
    .mercedes::after { background: linear-gradient(45deg, #e96443, #904e95); }

    /* Base colors for buttons before hover */
    .porsche { background: linear-gradient(to right, #c10011, darkred); }
    .ferrari { background: linear-gradient(to right, #c10011, darkred); }
    .lamborghini { background: linear-gradient(to right, #c10011, darkred); }
